CREATE TABLE "better_supabase"."moderation_actions" (
  "id"          uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"   uuid                     NOT NULL,
  "item_id"     uuid                     NOT NULL,
  "action"      text                     NOT NULL,
  "from_status" text,
  "to_status"   text                     NOT NULL,
  "reason"      text,
  "actor_id"    uuid,
  "created_at"  timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "moderation_actions_action_check"
    CHECK ((action = ANY (ARRAY['submit'::text, 'approve'::text, 'hide'::text, 'remove'::text, 'restore'::text, 'ban'::text, 'auto_hide'::text]))),
  CONSTRAINT "moderation_actions_pkey" PRIMARY KEY (id)
);

ALTER TABLE "better_supabase"."moderation_actions"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."moderation_bans" (
  "id"         uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"  uuid                     NOT NULL,
  "user_id"    uuid                     NOT NULL,
  "reason"     text,
  "banned_by"  uuid,
  "expires_at" timestamp with time zone,
  "lifted_by"  uuid,
  "lifted_at"  timestamp with time zone,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "moderation_bans_pkey" PRIMARY KEY (id),
  CONSTRAINT "moderation_bans_reason_check" CHECK (((reason IS NULL) OR (length(reason) <= 1000)))
);

ALTER TABLE "better_supabase"."moderation_bans"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."moderation_items" (
  "id"           uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"    uuid                     NOT NULL,
  "subject_type" text                     NOT NULL,
  "subject_id"   text                     NOT NULL,
  "author_id"    uuid,
  "status"       text                     NOT NULL DEFAULT 'visible'::text,
  "open_reports" integer                  NOT NULL DEFAULT 0,
  "reason"       text,
  "decided_by"   uuid,
  "decided_at"   timestamp with time zone,
  "created_at"   timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"   timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "moderation_items_open_reports_check" CHECK ((open_reports >= 0)),
  CONSTRAINT "moderation_items_pkey" PRIMARY KEY (id),
  CONSTRAINT "moderation_items_reason_check" CHECK (((reason IS NULL) OR (length(reason) <= 1000))),
  CONSTRAINT "moderation_items_status_check" CHECK ((status = ANY (ARRAY['pending'::text, 'visible'::text, 'hidden'::text, 'removed'::text]))),
  CONSTRAINT "moderation_items_subject_id_check" CHECK (((length(subject_id) >= 1) AND (length(subject_id) <= 200))),
  CONSTRAINT "moderation_items_subject_type_check" CHECK ((subject_type ~ '^[a-z][a-z0-9_-]{0,62}$'::text)),
  CONSTRAINT "moderation_items_tenant_id_subject_type_subject_id_key" UNIQUE (tenant_id, subject_type, subject_id)
);

ALTER TABLE "better_supabase"."moderation_items"
  ENABLE ROW LEVEL SECURITY;

