CREATE OR REPLACE FUNCTION better_supabase.unban_user (
  ban_id uuid
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_row "better_supabase"."moderation_bans";
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."moderation_bans" x where x."id" = unban_user.ban_id for update;
  if v_row."id" is null then
    raise exception 'ban not found' using errcode = 'P0002', hint = 'MODERATION_BAN_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_row."tenant_id", 'moderation.ban'), false)) then
    raise exception 'not allowed to lift bans' using errcode = '42501', hint = 'MODERATION_FORBIDDEN';
  end if;
  if v_row."lifted_at" is not null then
    return false;
  end if;
  update "better_supabase"."moderation_bans" x set "lifted_at" = now(), "lifted_by" = auth.uid()
  where x."id" = v_row."id"
  returning * into v_row;
  perform "better_supabase".emit_event('moderation_ban.lifted', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'userId', v_row."user_id", 'expiresAt', v_row."expires_at"), 'moderation-bans/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/moderation');
  perform better_supabase.audit_event(
    event_type => 'moderation_ban.lifted',
    category => 'security',
    target_type => 'user',
    record_id => v_row."user_id"::text,
    summary => 'lifted a ban',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'userId', v_row."user_id", 'expiresAt', v_row."expires_at")
  );
  return true;
end;
$function$;

ALTER TABLE "better_supabase"."moderation_bans"
  ADD CONSTRAINT "moderation_bans_user_id_fkey" FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;

ALTER TABLE "better_supabase"."moderation_items"
  ADD CONSTRAINT "moderation_items_author_id_fkey" FOREIGN KEY (author_id) REFERENCES auth.users(id) ON DELETE SET NULL;

ALTER TABLE "better_supabase"."moderation_actions"
  ADD CONSTRAINT "moderation_actions_item_id_fkey" FOREIGN KEY (item_id) REFERENCES better_supabase.moderation_items(id) ON DELETE CASCADE;

ALTER TABLE "better_supabase"."moderation_reports"
  ADD CONSTRAINT "moderation_reports_item_id_fkey" FOREIGN KEY (item_id) REFERENCES better_supabase.moderation_items(id) ON DELETE CASCADE;

ALTER TABLE "better_supabase"."moderation_reports"
  ADD CONSTRAINT "moderation_reports_reporter_id_fkey" FOREIGN KEY (reporter_id) REFERENCES auth.users(id) ON DELETE CASCADE;

CREATE INDEX moderation_actions_item_idx ON better_supabase.moderation_actions USING btree (item_id, created_at DESC);

CREATE UNIQUE INDEX moderation_bans_active_idx ON better_supabase.moderation_bans USING btree (tenant_id, user_id)
  WHERE (lifted_at IS NULL);

CREATE INDEX moderation_bans_user_idx ON better_supabase.moderation_bans USING btree (user_id);

CREATE INDEX moderation_items_author_idx ON better_supabase.moderation_items USING btree (author_id);

CREATE INDEX moderation_items_queue_idx ON better_supabase.moderation_items USING btree (tenant_id, updated_at DESC)
  WHERE ((status = 'pending'::text) OR (open_reports > 0));

CREATE INDEX moderation_items_status_idx ON better_supabase.moderation_items USING btree (tenant_id, status, updated_at DESC);

CREATE INDEX moderation_reports_item_idx ON better_supabase.moderation_reports USING btree (item_id, created_at DESC);

CREATE UNIQUE INDEX moderation_reports_open_idx ON better_supabase.moderation_reports USING btree (item_id, reporter_id)
  WHERE (status = 'open'::text);

CREATE INDEX moderation_reports_reporter_idx ON better_supabase.moderation_reports USING btree (reporter_id);

CREATE TRIGGER bs_comments_moderation_guard
  BEFORE INSERT ON better_supabase.comments
  FOR EACH ROW
  EXECUTE FUNCTION better_supabase.comments_moderation_guard();

CREATE POLICY "comments_moderation" ON "better_supabase"."comments"
  AS RESTRICTIVE
  FOR SELECT
  TO "authenticated"
  USING
    (((author_id = ( SELECT auth.uid() AS uid)) OR (NOT better_supabase.moderation_hidden('comment'::text, (id)::text)) OR (organization_id IN ( SELECT
    better_supabase.tenant_ids_with('moderation.read'::text) AS tenant_ids_with))));

CREATE POLICY "moderation_actions_read" ON "better_supabase"."moderation_actions"
  FOR SELECT
  TO "authenticated"
  USING ((tenant_id IN ( SELECT better_supabase.tenant_ids_with('moderation.read'::text) AS tenant_ids_with)));

CREATE POLICY "moderation_bans_read" ON "better_supabase"."moderation_bans"
  FOR SELECT
  TO "authenticated"
  USING (((user_id = ( SELECT auth.uid() AS uid)) OR (tenant_id IN ( SELECT better_supabase.tenant_ids_with('moderation.read'::text) AS tenant_ids_with))));

CREATE POLICY "moderation_items_read" ON "better_supabase"."moderation_items"
  FOR SELECT
  TO "authenticated"
  USING ((tenant_id IN ( SELECT better_supabase.tenant_ids_with('moderation.read'::text) AS tenant_ids_with)));

CREATE POLICY "moderation_reports_read" ON "better_supabase"."moderation_reports"
  FOR SELECT
  TO "authenticated"
  USING (((reporter_id = ( SELECT auth.uid() AS uid)) OR (tenant_id IN ( SELECT better_supabase.tenant_ids_with('moderation.read'::text) AS tenant_ids_with))));

